==== RequireOwnerFields ====
package org.springframework.samples.petclinic.rest.function.owner;

import java.util.ArrayList;
import java.util.List;

import net.officefloor.plugin.variable.Out;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.rest.escalation.MissingOwnerFieldsException;
import org.springframework.web.bind.annotation.RequestBody;

/**
 * First step of {@code POST /api/owners}: rejects a body that is missing or blank in any
 * required field (firstName, lastName, address, city, telephone) before {@link BuildOwner}
 * runs, so such a request is a 400 listing the offending fields rather than a persisted owner.
 *
 * <p>Reads the raw body (no {@code @Valid}) so this check runs ahead of bean validation and
 * owns the response format; the body is republished for later steps.
 *
 * <p>The address is normalized in place first (see {@link AddressNormalizer}) so the required
 * check rejects an address that is blank <em>after</em> normalization, and every later step
 * sees — and the response returns — the normalized address.
 */
public class RequireOwnerFields {

    public void service(@RequestBody OwnerFieldsDto request, Out<OwnerFieldsDto> validated)
            throws MissingOwnerFieldsException {
        request.setAddress(AddressNormalizer.normalize(request.getAddress()));
        List<String> missing = new ArrayList<>();
        if (isBlank(request.getFirstName())) {
            missing.add("firstName");
        }
        if (isBlank(request.getLastName())) {
            missing.add("lastName");
        }
        if (isBlank(request.getAddress())) {
            missing.add("address");
        }
        if (isBlank(request.getCity())) {
            missing.add("city");
        }
        if (isBlank(request.getTelephone())) {
            missing.add("telephone");
        }
        if (!missing.isEmpty()) {
            throw new MissingOwnerFieldsException(missing);
        }
        validated.set(request);
    }

    private static boolean isBlank(String value) {
        return value == null || value.isBlank();
    }
}
==== NormalizeOwnerEmail ====
package org.springframework.samples.petclinic.rest.function.owner;

import java.util.Locale;
import java.util.regex.Pattern;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.rest.escalation.InvalidEmailException;

/**
 * Normalizes the optional owner {@code email}. Email may be omitted; when present it must
 * be a syntactically valid address. A valid address is stored lower-cased (so it is later
 * mapped onto the {@link org.springframework.samples.petclinic.model.Owner} and returned
 * lower-cased); a present-but-invalid address is rejected 400 via
 * {@link InvalidEmailException}. A blank value is treated as absent.
 *
 * <p>Mutates the published body in place, mirroring {@link NormalizeOwnerTelephone}.
 */
public class NormalizeOwnerEmail {

    /**
     * Syntactic email check: a non-empty local part, an '@', then a domain with at least one
     * dot and non-empty labels, none of the parts containing whitespace or a second '@'.
     */
    private static final Pattern EMAIL = Pattern.compile("^[^\\s@]+@[^\\s@.]+(\\.[^\\s@.]+)+$");

    public void service(@Val OwnerFieldsDto request) throws InvalidEmailException {
        String email = request.getEmail();
        if (email == null || email.isBlank()) {
            request.setEmail(null);
            return;
        }
        String trimmed = email.trim();
        if (!EMAIL.matcher(trimmed).matches()) {
            throw new InvalidEmailException("Email must be a syntactically valid address");
        }
        request.setEmail(trimmed.toLowerCase(Locale.ROOT));
    }
}
==== NormalizeOwnerTelephone ====
package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.rest.escalation.InvalidTelephoneException;

/**
 * Normalizes the create-owner telephone into E.164 form (see {@link E164Telephone}): a
 * leading '+' and country code are kept when present, otherwise country code '+61' is
 * assumed and a single leading '0' is dropped from the national digits; spaces, dashes and
 * brackets are stripped and the result must carry 8 to 15 digits after the '+'. Runs after
 * {@link RequireOwnerFields} (so the field is present) and before {@link BuildOwner},
 * mutating the published body in place so the mapped
 * {@link org.springframework.samples.petclinic.model.Owner} — and the response — carries
 * the E.164 value. A telephone that cannot form valid E.164 is rejected 400 via
 * {@link InvalidTelephoneException}.
 */
public class NormalizeOwnerTelephone {

    public void service(@Val OwnerFieldsDto request) throws InvalidTelephoneException {
        request.setTelephone(E164Telephone.normalize(request.getTelephone()));
    }
}

