==== RejectDuplicateHousehold ====
package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.rest.escalation.DuplicateHouseholdException;
import org.springframework.samples.petclinic.repository.OwnerRepository;

/**
 * Rejects a create-owner request that shares a household with an existing owner: same
 * last name (compared case-insensitively with runs of whitespace collapsed to a single
 * space) and same address (compared in the normalized form of {@link AddressNormalizer}).
 * Runs before {@link BuildOwner}. A collision is rejected 409 via
 * {@link DuplicateHouseholdException}, unless the request opts in with
 * {@code sharesHousehold} set true.
 */
public class RejectDuplicateHousehold {

    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
            throws DuplicateHouseholdException {
        if (Boolean.TRUE.equals(request.getSharesHousehold())) {
            return;
        }
        String lastName = normalize(request.getLastName());
        String address = AddressNormalizer.normalize(request.getAddress());
        for (Owner existing : ownerRepository.findAll()) {
            if (normalize(existing.getLastName()).equals(lastName)
                    && AddressNormalizer.normalize(existing.getAddress()).equals(address)) {
                throw new DuplicateHouseholdException(
                        "Another owner with the same last name and address already exists");
            }
        }
    }

    private static String normalize(String value) {
        if (value == null) {
            return "";
        }
        return value.trim().replaceAll("\\s+", " ").toLowerCase();
    }
}
==== AssignCustomerCode ====
package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;

/**
 * Assigns the owner's {@code customerCode}, formatted {@code <LAST3>-<NNNN>} where
 * LAST3 is the upper-cased first three letters of the last name and NNNN is a global
 * 4-digit zero-padded sequence equal to one more than the current number of owners
 * (e.g. {@code SMI-0007}).
 *
 * <p>Runs after {@code BuildOwner} (so the owner exists) but before {@code SaveOwner}
 * (so the owner being created is not yet counted), mutating the owner in place.
 */
public class AssignCustomerCode {

    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
        int sequence = ownerRepository.findAll().size() + 1;
        String lastName = owner.getLastName();
        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase();
        owner.setCustomerCode(String.format("%s-%04d", last3, sequence));
    }
}
==== AssignHousehold ====
package org.springframework.samples.petclinic.rest.function.owner;

import java.nio.charset.StandardCharsets;
import java.util.UUID;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.repository.OwnerRepository;

/**
 * Assigns a shared {@code householdId} when a create-owner request opts in with
 * {@code sharesHousehold} and an existing owner shares its household: same last name
 * (compared case-insensitively with runs of whitespace collapsed to a single space) and
 * same address (compared in the normalized form of {@link AddressNormalizer}), the same
 * identity {@link RejectDuplicateHousehold} uses. Both the new owner and
 * every existing household member are assigned the same identifier, derived deterministically
 * from the normalized last name and address, so members always agree on it and it never
 * changes as more join.
 *
 * <p>Runs after {@link BuildOwner} (so the Owner exists) and within the create transaction
 * (so any backfilled members commit with the new owner). When {@code sharesHousehold} is not
 * set, or no existing owner shares the household, no id is assigned.
 */
public class AssignHousehold {

    public void service(@Val Owner owner, @Val OwnerFieldsDto request, OwnerRepository ownerRepository) {
        if (!Boolean.TRUE.equals(request.getSharesHousehold())) {
            return;
        }
        String lastName = normalize(owner.getLastName());
        String address = AddressNormalizer.normalize(owner.getAddress());
        String householdId = householdId(lastName, address);
        boolean shared = false;
        for (Owner existing : ownerRepository.findAll()) {
            if (normalize(existing.getLastName()).equals(lastName)
                    && AddressNormalizer.normalize(existing.getAddress()).equals(address)) {
                shared = true;
                if (!householdId.equals(existing.getHouseholdId())) {
                    existing.setHouseholdId(householdId);
                    ownerRepository.save(existing);
                }
            }
        }
        if (shared) {
            owner.setHouseholdId(householdId);
        }
    }

    private static String householdId(String lastName, String address) {
        byte[] key = (lastName + "\n" + address).getBytes(StandardCharsets.UTF_8);
        return UUID.nameUUIDFromBytes(key).toString();
    }

    private static String normalize(String value) {
        if (value == null) {
            return "";
        }
        return value.trim().replaceAll("\\s+", " ").toLowerCase();
    }
}
